    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != bg]
    if not pts:
        return out
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    color = grid[pts[0][0]][pts[0][1]]

    # A long contiguous stroke identifies an intentional horizontal or
    # vertical line. Mark its missing cells (within the object's full bounds)
    # with 2, while preserving the original stroke color.
    horizontal = []
    for r in range(r0, r1 + 1):
        longest = run = 0
        for c in range(c0, c1 + 1):
            if grid[r][c] == color:
                run += 1
                longest = max(longest, run)
            else:
                run = 0
        if longest >= 3:
            horizontal.append(r)
    vertical = []
    for c in range(c0, c1 + 1):
        longest = run = 0
        for r in range(r0, r1 + 1):
            if grid[r][c] == color:
                run += 1
                longest = max(longest, run)
            else:
                run = 0
        if longest >= 3:
            vertical.append(c)
    for r in horizontal:
        for c in range(c0, c1 + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    for c in vertical:
        for r in range(r0, r1 + 1):
            if out[r][c] == bg:
                out[r][c] = 2
    return out
